// ---- logging ----
var logFormat = "json"
var experimentalEnabled = false

func initLogFormat() {
	f := os.Getenv("GOMPLATE_LOG_FORMAT")
	if f == "" {
		// default: json when non-interactive, console when interactive?
		// For now, default to json (matches non-tty). Check if stderr is tty?
		// Use simple heuristic: if TERM set and stderr is char device? We'll just default json.
		// To match original: when run in terminal, default console. We detect tty via Stat.
		if isTerminal() {
			logFormat = "console"
		} else {
			logFormat = "json"
		}
		return
	}
	switch f {
	case "json", "console", "logfmt", "simple":
		logFormat = f
	default:
		logFormat = "json"
	}
}

func isTerminal() bool {
	fi, err := os.Stderr.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func escapeLog(s string) string {
	// for logfmt/simple/console err="..." quoting: escape ", \, \n?
