func writeJSONStr(buf *bytes.Buffer, s string) {
	b, _ := jsonMarshalStr(s)
	buf.Write(b)
}
func jsonMarshalStr(s string) ([]byte, error) {
	// use simple quoting
	var buf bytes.Buffer
	buf.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			buf.WriteString("\\\"")
		case '\\':
			buf.WriteString("\\\\")
		case '\n':
			buf.WriteString("\\n")
		case '\r':
			buf.WriteString("\\r")
		case '\t':
			buf.WriteString("\\t")
		default:
			if r < 0x20 {
				fmt.Fprintf(&buf, "\\u%04x", r)
			} else {
				buf.WriteRune(r)
			}
		}
	}
	buf.WriteByte('"')
	return buf.Bytes(), nil
}
func writeJSONVal(buf *bytes.Buffer, v interface{}) {
	switch x := v.(type) {
	case string:
		writeJSONStr(buf, x)
	case bool:
		if x {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case int:
		fmt.Fprintf(buf, "%d", x)
	case int64:
		fmt.Fprintf(buf, "%d", x)
	case uint64:
		fmt.Fprintf(buf, "%d", x)
	case float64:
		fmt.Fprintf(buf, "%v", x)
	case []string:
		buf.WriteByte('[')
		for i, s := range x {
			if i > 0 {
				buf.WriteByte(',')
			}
			// original uses ["echo","hi"] without spaces? In postExec verbose: "args":["echo","hi"] – no spaces. Good.
			writeJSONStr(buf, s)
		}
		buf.WriteByte(']')
	default:
		// fallback
		b, _ := jsonMarshalGeneric(v)
		buf.Write(b)
	}
}
func jsonMarshalGeneric(v interface{}) ([]byte, error) {
	// simple
	switch x := v.(type) {
	case []interface{}:
		var buf bytes.Buffer
		buf.WriteByte('[')
		for i, e := range x {
			if i > 0 {
				buf.WriteByte(',')
			}
			b, _ := jsonMarshalGeneric(e)
			buf.Write(b)
		}
		buf.WriteByte(']')
		return buf.Bytes(), nil
	default:
		return []byte(fmt.Sprintf("%v", v)), nil
	}
}

