		if f.NoOptDefVal != "" {
			return false
		}
		return true
	} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
		// short flag(s)
		// could be "-d", "-Vd", "-ihello", "-i=hi", "-d=a=b", etc.
		// If contains "=", then value provided via "=", check part before "="?
