		// e.g., "-ihello" – i needs value, but attached "hello", so next arg is not value.
		// e.g., "-V" – bool, no value needed.
		// e.g., "-d" – needs value, next is value.
		// Implement: iterate chars after "-", check each flag's type.
		shorthands := arg[1:]
		for idx, ch := range shorthands {
			name := string(ch)
			// find flag by shorthand
			var found *pflag.Flag
			fs.VisitAll(func(f *pflag.Flag) {
				if f.Shorthand == name {
					found = f
				}
			})
			if found == nil {
				// unknown shorthand, ignore
				continue
			}
			isBool := found.NoOptDefVal != ""
			if isBool {
				// bool, continue to next char
				continue
			} else {
				// needs value: if there are remaining chars after this (attached value), then value provided, return false. Else, next arg is value, return true.
				if idx < len(shorthands)-1 {
					// attached value present (e.g., "-ihello" – after 'i', there is "hello")
					return false
				} else {
					// last char needs value, no attached, so next arg is value
					return true
				}
			}
		}
		// all bools, no value needed
		return false
	}
	return false
}

