func isURL(s string) bool {
	// check if contains "://" or scheme ":"? For dynamic, "file://...", "env:///FOO", "https://...", "merge:...", "stdin:...", etc.
	// Plain "person.json" is not URL (no colon). "env:FOO" contains colon, is URL. "file:rel.json" contains colon, is URL.
	// What about "a=b"? Contains "=", not colon, not URL. So check for ":"?
	// But Windows paths like "C:\\..." contain colon, would be misidentified. Ignore Windows.
	if strings.Contains(s, "://") {
		return true
	}
	// check scheme: before ":" is valid scheme? Scheme is [a-zA-Z][a-zA-Z0-9+.-]*. And after ":"?
	if idx := strings.Index(s, ":"); idx > 0 {
		scheme := s[:idx]
		// check scheme valid?
		for i, c := range scheme {
			if i == 0 {
				if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
					return false
				}
			} else {
				if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.') {
					return false
				}
			}
		}
		return true
	}
	return false
}

func joinURLSubpath(urlStr, subpath string) string {
	// if urlStr has scheme, parse and join path?
	if isURL(urlStr) {
		// handle merge? merge:alias|alias with subpath? Probably not used. Ignore.
		// For file://, http://, etc., join path.
		// Simple: if urlStr contains "?", split query? Subpath should be before query? For file with ?type=..., subpath? Probably not used with query. Ignore.
		// For now, just append: if urlStr ends with "/", urlStr+subpath, else urlStr+"/"+subpath, preserving query?
		if idx := strings.Index(urlStr, "?"); idx >= 0 {
			base := urlStr[:idx]
			query := urlStr[idx:]
			if strings.HasSuffix(base, "/") {
				return base + subpath + query
			}
			return base + "/" + subpath + query
		}
		if strings.HasSuffix(urlStr, "/") {
			return urlStr + subpath
		}
		return urlStr + "/" + subpath
	}
	// plain path
	return filepath.Join(urlStr, subpath)
}

