func headURLBase(fetchURL string) string {
	u, _ := url.Parse(fetchURL)
	if u == nil {
		return fetchURL
	}
	// base is scheme://host/ ? Original for http://127.0.0.1:port/data.json gave url "http://127.0.0.1:port/" and name "data.json".
