	if u == nil {
		return fetchURL
	}
	p := strings.TrimPrefix(u.Path, "/")
	return p
}

func mimeFromExt(ext string) string {
	switch ext {
	case ".json":
		return "application/json"
	case ".yaml", ".yml":
		return "application/yaml"
	case ".toml":
		return "application/toml"
	case ".csv":
		return "text/csv"
	case ".env":
		return "application/x-env"
	case ".txt", "":
		return "text/plain"
	default:
		// unknown extension -> text/plain? Or error? Earlier .txt with json content returned raw string, so text/plain. For unknown like .foo? Probably text/plain as well? Or error "unsupported type"? Docs say "If an unsupported type is detected, gomplate will exit with an error." What types are unsupported? E.g., .xml? Let's test with .xml.
		return "text/plain"
	}
}

