		if err != nil {
			return nil, err
		}
		depth = d
		list = args[1]
	} else {
		return nil, fmt.Errorf("wrong number of args: wanted 1 or 2, got %d", len(args))
	}
	var arr []interface{}
	switch x := list.(type) {
	case []interface{}:
		arr = x
	case []string:
		for _, s := range x {
			arr = append(arr, s)
		}
	case nil:
		return []interface{}{}, nil
	default:
		return nil, fmt.Errorf("flatten: input must be list")
	}
	return flattenWithDepth(arr, int(depth)), nil
}
func flattenWithDepth(arr []interface{}, depth int) []interface{} {
	if depth == 0 {
		return arr
	}
	var res []interface{}
	for _, v := range arr {
		if sub, ok := v.([]interface{}); ok {
			if depth == -1 {
				res = append(res, flattenWithDepth(sub, -1)...)
			} else {
				res = append(res, flattenWithDepth(sub, depth-1)...)
