// file namespace
type fileNS struct{}
func (f fileNS) Exists(path interface{}) (bool, error) {
	_, err := os.Stat(toString(path))
	if err == nil {
		return true, nil
	}
	if os.IsNotExist(err) {
		return false, nil
	}
	return false, err
